package com.airportshuttle;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Stream;
import org.springframework.web.client.RestClient;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import static com.airportshuttle.Auth.*;
import static com.airportshuttle.TripService.*;
@RestController
@RequestMapping("/api")
public class Api {
 private final TripService trips;private final JdbcTemplate db;private final VehicleCatalogService vehicleCatalog;
 private final BCryptPasswordEncoder passwordEncoder=new BCryptPasswordEncoder();
 private final RestClient photon=RestClient.builder().baseUrl("https://photon.komoot.io").defaultHeader("User-Agent","AirportShuttle/1.0 contact@airport-shuttle.local").build();
 public Api(TripService trips,JdbcTemplate db,VehicleCatalogService vehicleCatalog){this.trips=trips;this.db=db;this.vehicleCatalog=vehicleCatalog;}
 public record DriverCreate(@NotBlank @Size(max=100) String name,@NotBlank @Email @Size(max=190) String email,@NotBlank @Size(max=30) String phone,@NotBlank @Size(min=10,max=72) String password,@Size(max=100) String vehicle,@Min(1) @Max(100) int seats,@Min(0) @Max(100) int luggageCapacity) {}
 public record DriverUpdate(@NotBlank @Size(max=100) String name,@NotBlank @Email @Size(max=190) String email,@NotBlank @Size(max=30) String phone,@Size(max=100) String vehicle,@Min(1) @Max(100) int seats,@Min(0) @Max(100) int luggageCapacity) {}
 public record VehicleCreate(@Min(1990) @Max(2100) int year,@NotBlank @Size(max=60) String make,@NotBlank @Size(max=80) String model,@NotBlank @Size(max=40) String color,@NotBlank @Size(max=20) String doors,@Min(1) @Max(100) int seatbelts,boolean wheelchairRamp,@Size(max=40) String licensePlate,@Size(max=40) String vin,@Size(max=120) String engineType,@Min(0) @Max(2000000) Integer mileage) {}
 @GetMapping("/health") public Map<String,String> health(){db.queryForObject("SELECT 1",Integer.class);return Map.of("status","ok");}
 @GetMapping("/vehicle-reference") public Map<String,Object> vehicleReference(@RequestParam(required=false) Integer year,@RequestParam(required=false) String make,@RequestParam(required=false) String model){return Map.of("years",vehicleCatalog.years(),"makes",vehicleCatalog.makes(year),"models",year!=null&&make!=null&&!make.isBlank()?vehicleCatalog.models(year,make):List.of(),"engineTypes",year!=null&&make!=null&&model!=null&&!model.isBlank()?vehicleCatalog.engines(year,make,model):List.of());}
 @GetMapping("/locations") public List<Location> locations(){return trips.locations();}
 @GetMapping("/places/search") public List<Map<String,Object>> searchPlaces(@RequestParam String q){if(q==null||q.trim().length()<2)return List.of();Map<?,?> response=photon.get().uri(uri->uri.path("/api").queryParam("q",q.trim()).queryParam("limit",8).queryParam("lang","en").queryParam("bbox","-8.15,12.45,-7.75,12.75").build()).retrieve().body(Map.class);if(response==null||!(response.get("features") instanceof List<?> features))return List.of();List<Map<String,Object>> results=new ArrayList<>();for(Object item:features){if(!(item instanceof Map<?,?> feature)||!(feature.get("geometry") instanceof Map<?,?> geometry)||!(geometry.get("coordinates") instanceof List<?> coordinates)||coordinates.size()<2)continue;Map<?,?> props=feature.get("properties") instanceof Map<?,?> p?p:Map.of();Object rawName=props.get("name");String name=rawName==null?q.trim():String.valueOf(rawName);String detail=String.join(", ",Stream.of(props.get("street"),props.get("city"),props.get("country")).filter(Objects::nonNull).map(String::valueOf).filter(s->!s.isBlank()).toList());results.add(Map.of("name",name,"detail",detail,"lat",((Number)coordinates.get(1)).doubleValue(),"lng",((Number)coordinates.get(0)).doubleValue(),"airport",name.toLowerCase(Locale.ROOT).contains("airport")||name.toLowerCase(Locale.ROOT).contains("aéroport")));}return results;}
 @PostMapping("/locations/resolve") public Location resolve(@RequestBody Map<String,Object> input,HttpServletRequest r){User u=user(r);String name=String.valueOf(input.getOrDefault("name",""));String detail=String.valueOf(input.getOrDefault("detail",""));double lat=((Number)input.get("lat")).doubleValue(),lng=((Number)input.get("lng")).doubleValue();boolean airport=Boolean.TRUE.equals(input.get("airport"));List<Location> existing=trips.locations();return existing.stream().filter(l->l.name().equals(name)&&Math.abs(l.lat()-lat)<.0001&&Math.abs(l.lng()-lng)<.0001).findFirst().orElseGet(()->{db.update("INSERT INTO locations(name,detail,lat,lng,airport) VALUES(?,?,?,?,?)",name,detail,lat,lng,airport);return trips.locations().stream().max(Comparator.comparingLong(Location::id)).orElseThrow();});}
 @GetMapping("/trips") public List<Trip> list(HttpServletRequest r){return trips.list(user(r));}
 @GetMapping("/trips/{id}") public Trip get(@PathVariable long id,HttpServletRequest r){return trips.get(id,user(r));}
 @PostMapping("/trips") public Trip book(@Valid @RequestBody Booking b,HttpServletRequest r){return trips.book(user(r),b);}
 @PutMapping("/trips/{id}/assignment") public Trip assign(@PathVariable long id,@Valid @RequestBody Assign a,HttpServletRequest r){return trips.assign(id,user(r),a);}
 @PutMapping("/trips/{id}/status") public Trip status(@PathVariable long id,@Valid @RequestBody Status s,HttpServletRequest r){return trips.status(id,user(r),s);}
 @PutMapping("/trips/{id}/route") public Trip route(@PathVariable long id,@Valid @RequestBody Route route,HttpServletRequest r){return trips.route(id,user(r),route);}
 @PutMapping("/trips/{id}/location") public Trip position(@PathVariable long id,@Valid @RequestBody Position p,HttpServletRequest r){return trips.position(id,user(r),p);}
 @GetMapping("/trips/{id}/events") public List<Map<String,Object>> events(@PathVariable long id,HttpServletRequest r){return trips.events(id,user(r));}
 @GetMapping("/drivers") public List<Map<String,Object>> drivers(HttpServletRequest r){return trips.drivers(user(r));}
 @PostMapping("/drivers") public Map<String,Object> createDriver(@Valid @RequestBody DriverCreate input,HttpServletRequest r){role(user(r),"DISPATCHER");String email=input.email().trim().toLowerCase(Locale.ROOT);try{db.update("INSERT INTO users(name,email,phone,password_hash,role,vehicle,seats,luggage_capacity) VALUES(?,?,?,?,'DRIVER',?,?,?)",input.name().trim(),email,input.phone().trim(),passwordEncoder.encode(input.password()),input.vehicle()==null?"":input.vehicle().trim(),input.seats(),input.luggageCapacity());}catch(org.springframework.dao.DuplicateKeyException ex){throw error(409,"An account with this email already exists.");}long id=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,email);return driver(id);}
 @GetMapping("/vehicles") public List<Map<String,Object>> vehicles(HttpServletRequest r){role(user(r),"DISPATCHER");return db.queryForList("SELECT v.id,v.vehicle_year AS year,v.make,v.model,v.color,v.doors,v.seatbelts,v.wheelchair_ramp AS wheelchairRamp,v.license_plate AS licensePlate,v.vin,v.engine_type AS engineType,v.mileage,v.active,u.id AS driverId,u.name AS driverName,u.phone AS driverPhone FROM vehicles v LEFT JOIN users u ON u.vehicle_id=v.id AND u.role='DRIVER' AND u.active=true WHERE v.active=true ORDER BY v.vehicle_year DESC,v.make,v.model");}
 @PostMapping("/vehicles") public Map<String,Object> createVehicle(@Valid @RequestBody VehicleCreate input,HttpServletRequest r){role(user(r),"DISPATCHER");db.update("INSERT INTO vehicles(vehicle_year,make,model,color,doors,seatbelts,wheelchair_ramp,license_plate,vin,engine_type,mileage) VALUES(?,?,?,?,?,?,?,?,?,?,?)",input.year(),input.make().trim(),input.model().trim(),input.color().trim(),input.doors().trim(),input.seatbelts(),input.wheelchairRamp(),blank(input.licensePlate()),blank(input.vin()),blank(input.engineType()),input.mileage());long id=db.queryForObject("SELECT id FROM vehicles ORDER BY id DESC LIMIT 1",Long.class);return vehicle(id);}
 @PutMapping("/vehicles/{id}") public Map<String,Object> updateVehicle(@PathVariable long id,@Valid @RequestBody VehicleCreate input,HttpServletRequest r){role(user(r),"DISPATCHER");if(db.queryForObject("SELECT COUNT(*) FROM vehicles WHERE id=? AND active=true",Integer.class,id)==0)throw error(404,"Vehicle not found.");db.update("UPDATE vehicles SET vehicle_year=?,make=?,model=?,color=?,doors=?,seatbelts=?,wheelchair_ramp=?,license_plate=?,vin=?,engine_type=?,mileage=? WHERE id=? AND active=true",input.year(),input.make().trim(),input.model().trim(),input.color().trim(),input.doors().trim(),input.seatbelts(),input.wheelchairRamp(),blank(input.licensePlate()),blank(input.vin()),blank(input.engineType()),input.mileage(),id);return vehicle(id);}
 private Map<String,Object> vehicle(long id){return db.queryForMap("SELECT v.id,v.vehicle_year AS year,v.make,v.model,v.color,v.doors,v.seatbelts,v.wheelchair_ramp AS wheelchairRamp,v.license_plate AS licensePlate,v.vin,v.engine_type AS engineType,v.mileage,v.active,u.id AS driverId,u.name AS driverName,u.phone AS driverPhone FROM vehicles v LEFT JOIN users u ON u.vehicle_id=v.id AND u.role='DRIVER' WHERE v.id=?",id);}
 private String blank(String value){return value==null?null:value.trim();}
 @PutMapping("/drivers/{id}") public Map<String,Object> updateDriver(@PathVariable long id,@Valid @RequestBody DriverUpdate input,HttpServletRequest r){role(user(r),"DISPATCHER");if(db.queryForObject("SELECT COUNT(*) FROM users WHERE id=? AND role='DRIVER' AND active=true",Integer.class,id)==0)throw error(404,"Driver not found.");String email=input.email().trim().toLowerCase(Locale.ROOT);try{db.update("UPDATE users SET name=?,email=?,phone=?,vehicle=?,seats=?,luggage_capacity=? WHERE id=? AND role='DRIVER' AND active=true",input.name().trim(),email,input.phone().trim(),input.vehicle()==null?"":input.vehicle().trim(),input.seats(),input.luggageCapacity(),id);}catch(org.springframework.dao.DuplicateKeyException ex){throw error(409,"An account with this email already exists.");}return driver(id);}
 @DeleteMapping("/drivers/{id}") public Map<String,Boolean> deleteDriver(@PathVariable long id,HttpServletRequest r){role(user(r),"DISPATCHER");if(db.queryForObject("SELECT COUNT(*) FROM users WHERE id=? AND role='DRIVER' AND active=true",Integer.class,id)==0)throw error(404,"Driver not found.");if(db.queryForObject("SELECT COUNT(*) FROM trips WHERE driver_id=? AND status NOT IN ('COMPLETED','CANCELLED')",Integer.class,id)>0)throw error(409,"This driver has an active trip and cannot be removed.");db.update("UPDATE users SET active=false,vehicle_id=NULL,vehicle='' WHERE id=? AND role='DRIVER'",id);return Map.of("ok",true);}
 private Map<String,Object> driver(long id){return db.queryForMap("SELECT u.id,u.name,u.email,u.phone,u.role,u.vehicle,u.seats,u.luggage_capacity AS luggageCapacity,u.vehicle_id AS vehicleId,CASE WHEN v.id IS NULL THEN NULL ELSE CONCAT(v.vehicle_year,' ',v.make,' ',v.model,' · ',v.color) END AS vehicleLabel FROM users u LEFT JOIN vehicles v ON v.id=u.vehicle_id AND v.active=true WHERE u.id=? AND u.role='DRIVER' AND u.active=true",id);}
 @DeleteMapping("/vehicles/{id}") public Map<String,Boolean> deleteVehicle(@PathVariable long id,HttpServletRequest r){role(user(r),"DISPATCHER");if(db.queryForObject("SELECT COUNT(*) FROM vehicles WHERE id=? AND active=true",Integer.class,id)==0)throw error(404,"Vehicle not found.");db.update("UPDATE users SET vehicle_id=NULL,vehicle='' WHERE vehicle_id=?",id);db.update("UPDATE vehicles SET active=false WHERE id=?",id);return Map.of("ok",true);}
 @PostMapping("/vehicles/{vehicleId}/assignDriver/{driverId}") public Map<String,Object> assignDriver(@PathVariable long vehicleId,@PathVariable long driverId,HttpServletRequest r){role(user(r),"DISPATCHER");if(db.queryForObject("SELECT COUNT(*) FROM vehicles WHERE id=? AND active=true",Integer.class,vehicleId)==0)throw error(404,"Vehicle not found.");if(db.queryForObject("SELECT COUNT(*) FROM users WHERE id=? AND role='DRIVER' AND active=true",Integer.class,driverId)==0)throw error(404,"Driver not found.");db.update("UPDATE users SET vehicle_id=NULL,vehicle='' WHERE vehicle_id=?",vehicleId);db.update("UPDATE users u JOIN vehicles v ON v.id=? SET u.vehicle_id=v.id,u.vehicle=CONCAT(v.vehicle_year,' ',v.make,' ',v.model,' · ',v.color) WHERE u.id=? AND u.role='DRIVER' AND u.active=true",vehicleId,driverId);return vehicle(vehicleId);}
 @DeleteMapping("/vehicles/{vehicleId}/driver") public Map<String,Object> unassignDriver(@PathVariable long vehicleId,HttpServletRequest r){role(user(r),"DISPATCHER");db.update("UPDATE users SET vehicle_id=NULL,vehicle='' WHERE vehicle_id=?",vehicleId);return vehicle(vehicleId);}
 @GetMapping("/notifications") public List<Map<String,Object>> notifications(HttpServletRequest r){return db.queryForList("SELECT id,trip_id AS tripId,message,created_at AS createdAt,read_at AS readAt FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100",user(r).id());}
 @PutMapping("/notifications/{id}/read") public Map<String,Boolean> read(@PathVariable long id,HttpServletRequest r){db.update("UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?",id,user(r).id());return Map.of("ok",true);}
 @GetMapping("/trips/{id}/receipt") public ResponseEntity<byte[]> receipt(@PathVariable long id,@RequestParam(defaultValue="en") String language,HttpServletRequest r){
  Trip t=trips.get(id,user(r));if(!t.status().equals("COMPLETED"))throw error(409,"Receipts are available after completion.");
  boolean fr="fr".equalsIgnoreCase(language);String fare=fr?String.format(Locale.FRANCE,"%,d Francs CFA",Math.round(t.fareCents()/100.0*500)):"USD "+String.format(Locale.ROOT,"%.2f",t.fareCents()/100.0);
  String text=fr?"AIRPORT SHUTTLE\nReçu de trajet #AS-"+t.id()+"\nPassager: "+t.passengerName()+"\nPrise en charge: "+t.pickup().name()+"\nDestination: "+t.destination().name()+"\nHeure de prise en charge (UTC): "+t.pickupAt()+"\nVol: "+t.flight()+"\nPassagers: "+t.passengers()+" | Bagages: "+t.bags()+"\nChauffeur: "+t.driverName()+"\nTarif estimé: "+fare+"\nStatut: TERMINÉ\n\nRelevé de trajet uniquement. Aucun paiement n’a été encaissé par ce système.\n":"AIRPORT SHUTTLE\nTrip receipt #AS-"+t.id()+"\nPassenger: "+t.passengerName()+"\nPickup: "+t.pickup().name()+"\nDestination: "+t.destination().name()+"\nPickup time (UTC): "+t.pickupAt()+"\nFlight: "+t.flight()+"\nPassengers: "+t.passengers()+" | Bags: "+t.bags()+"\nDriver: "+t.driverName()+"\nEstimated fare: "+fare+"\nStatus: COMPLETED\n\nTrip record only. Payment has not been collected by this system.\n";
  return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=shuttle-"+id+"-receipt.txt").contentType(new MediaType("text","plain",StandardCharsets.UTF_8)).body(text.getBytes(StandardCharsets.UTF_8));
 }
}
